import software.amazon.awssdk.services.sqs.SqsClient;
import software.amazon.awssdk.services.sqs.model.*;
import software.amazon.awssdk.services.dynamodb.DynamoDbClient;
import software.amazon.awssdk.services.dynamodb.model.*;
import org.springframework.expression.ExpressionParser;
import org.springframework.expression.spel.standard.SpelExpressionParser;
import org.springframework.expression.spel.support.StandardEvaluationContext;
import java.util.Map;
import java.util.HashMap;

public class OrderEventProcessor {

    private final SqsClient sqsClient;
    private final DynamoDbClient dynamoDbClient;
    private final ExpressionParser parser = new SpelExpressionParser();
    private static final String QUEUE_URL = System.getenv("ORDER_QUEUE_URL");
    private static final String TABLE_NAME = "OrderEvents";

    public OrderEventProcessor(SqsClient sqsClient, DynamoDbClient dynamoDbClient) {
        this.sqsClient = sqsClient;
        this.dynamoDbClient = dynamoDbClient;
    }

    public void pollAndProcess() {
        ReceiveMessageRequest receiveRequest = ReceiveMessageRequest.builder()
                .queueUrl(QUEUE_URL)
                .maxNumberOfMessages(10)
                .waitTimeSeconds(20)
                .build();

        ReceiveMessageResponse response = sqsClient.receiveMessage(receiveRequest);

        for (Message message : response.messages()) {
            try {
                processMessage(message);
                deleteMessage(message);
            } catch (Exception e) {
                System.err.println("Failed to process message: " + e.getMessage());
            }
        }
    }

    private void processMessage(Message message) {
        Map<String, MessageAttributeValue> attrs = message.messageAttributes();
        String tenantId = attrs.containsKey("tenantId") 
            ? attrs.get("tenantId").stringValue() 
            : "unknown";
        String routingExpression = attrs.containsKey("routingRule")
            ? attrs.get("routingRule").stringValue()
            : "'default'";

        // Evaluate routing expression to determine processing tier
        StandardEvaluationContext context = new StandardEvaluationContext();
        context.setVariable("body", message.body());
        context.setVariable("tenantId", tenantId);
        context.setVariable("timestamp", System.currentTimeMillis());

        // SpEL evaluation of user-controlled message attribute
        String tier = parser.parseExpression(routingExpression).getValue(context, String.class);

        // Persist processed event to DynamoDB
        Map<String, AttributeValue> item = new HashMap<>();
        item.put("PK", AttributeValue.builder().s("TENANT#" + tenantId).build());
        item.put("SK", AttributeValue.builder().s("EVENT#" + System.currentTimeMillis()).build());
        item.put("body", AttributeValue.builder().s(message.body()).build());
        item.put("tier", AttributeValue.builder().s(tier).build());
        item.put("status", AttributeValue.builder().s("PROCESSED").build());

        PutItemRequest putRequest = PutItemRequest.builder()
                .tableName(TABLE_NAME)
                .item(item)
                .build();

        dynamoDbClient.putItem(putRequest);
    }

    private void deleteMessage(Message message) {
        sqsClient.deleteMessage(DeleteMessageRequest.builder()
                .queueUrl(QUEUE_URL)
                .receiptHandle(message.receiptHandle())
                .build());
    }

    // Utility: read back events for a tenant
    public Map<String, AttributeValue> getEvent(String tenantId, String sortKey) {
        Map<String, AttributeValue> key = new HashMap<>();
        key.put("PK", AttributeValue.builder().s("TENANT#" + tenantId).build());
        key.put("SK", AttributeValue.builder().s(sortKey).build());

        GetItemRequest getRequest = GetItemRequest.builder()
                .tableName(TABLE_NAME)
                .key(key)
                .build();

        return dynamoDbClient.getItem(getRequest).item();
    }
}
